import { v4 as uuidv4 } from 'uuid';
import { AppStatus, Chunk, Document } from '../shared/types';
import { PersistenceService } from './persistence-service';

const INDEX_META = 'index-meta.json';
const INDEX_ACTIVITY = 'index-activity.json';
const DOCUMENTS_META = 'documents-meta.json';
const CHUNKS_DIR = 'chunks';

interface IndexActivity {
  lastActivity: string;
  error: boolean;
}

export class IndexingService {
  private persistence: PersistenceService;

  constructor(persistence: PersistenceService) {
    this.persistence = persistence;
  }

  /** Start indexing documents. If documentId is provided, index only that document. */
  async startIndexing(documentId?: string): Promise<AppStatus> {
    const docsMeta = this.persistence.readJson<Document[]>(DOCUMENTS_META) ?? [];
    const chunksMeta = this.persistence.readJson<Record<string, string[]>>(INDEX_META) ?? {};
    const requestedDocs = documentId
      ? docsMeta.filter(doc => doc.id === documentId)
      : docsMeta;

    if (documentId && requestedDocs.length === 0) {
      this.writeActivity(true);
      return this.getStatus();
    }

    for (const doc of requestedDocs) {
      const content = this.persistence.readText(`content/${doc.id}.txt`);
      if (!content) {
        doc.status = 'error';
        continue;
      }

      doc.status = 'indexing';
      const chunks = this.chunkDocument(doc.id, content);
      this.persistence.writeJson(`${CHUNKS_DIR}/${doc.id}.json`, chunks);
      chunksMeta[doc.id] = chunks.map(c => c.id);
      doc.status = 'indexed';
      doc.chunks = chunks.length;
    }

    this.persistence.writeJson(INDEX_META, chunksMeta);
    this.persistence.writeJson(DOCUMENTS_META, docsMeta);
    this.writeActivity(requestedDocs.some(doc => doc.status === 'error'));
    return this.getStatus();
  }

  /** Get current indexing status. */
  getStatus(): AppStatus {
    const docs = this.persistence.readJson<Document[]>(DOCUMENTS_META) ?? [];
    const chunksMeta = this.persistence.readJson<Record<string, string[]>>(INDEX_META) ?? {};
    const activity = this.persistence.readJson<IndexActivity>(INDEX_ACTIVITY);
    const indexedDocuments = docs.filter(doc => Boolean(chunksMeta[doc.id])).length;
    const hasErrors = docs.some(doc => doc.status === 'error') || Boolean(activity?.error);
    const isReady = indexedDocuments === docs.length && docs.length > 0;

    return {
      documentsLoaded: docs.length,
      indexedDocuments,
      indexStatus: hasErrors ? 'error' : isReady ? 'ready' : indexedDocuments > 0 ? 'indexing' : 'idle',
      lastActivity: activity?.lastActivity ?? '',
    };
  }

  /** Remove persisted chunks for a deleted document. */
  deleteIndex(documentId: string): void {
    const chunksMeta = this.persistence.readJson<Record<string, string[]>>(INDEX_META) ?? {};
    delete chunksMeta[documentId];
    this.persistence.writeJson(INDEX_META, chunksMeta);
    this.persistence.delete(`${CHUNKS_DIR}/${documentId}.json`);
    this.writeActivity(false);
  }

  /** Get all chunks for a document. */
  getChunksForDocument(documentId: string): Chunk[] {
    return this.persistence.readJson<Chunk[]>(`${CHUNKS_DIR}/${documentId}.json`) ?? [];
  }

  /** Get all chunks across all documents. */
  getAllChunks(): Chunk[] {
    const chunksMeta = this.persistence.readJson<Record<string, string[]>>(INDEX_META) ?? {};
    const allChunks: Chunk[] = [];

    for (const docId of Object.keys(chunksMeta)) {
      const chunks = this.getChunksForDocument(docId);
      allChunks.push(...chunks);
    }

    return allChunks;
  }

  /** Split a document into chunks of ~500 characters at paragraph boundaries. */
  private chunkDocument(documentId: string, content: string): Chunk[] {
    const CHUNK_SIZE = 500;
    const chunks: Chunk[] = [];

    // Split on double newlines (paragraphs)
    const paragraphs = content.split(/\n\s*\n/).filter(p => p.trim().length > 0);

    let buffer = '';
    let chunkIndex = 0;

    for (const para of paragraphs) {
      if (buffer.length + para.length > CHUNK_SIZE && buffer.length > 0) {
        chunks.push(this.createChunk(documentId, chunkIndex++, buffer.trim()));
        buffer = para;
      } else {
        buffer += (buffer ? '\n\n' : '') + para;
      }
    }

    if (buffer.trim()) {
      chunks.push(this.createChunk(documentId, chunkIndex, buffer.trim()));
    }

    return chunks;
  }

  private createChunk(documentId: string, index: number, content: string): Chunk {
    return {
      id: uuidv4(),
      documentId,
      content,
      index,
      metadata: {
        charCount: String(content.length),
        wordCount: String(content.split(/\s+/).length),
      },
    };
  }

  private writeActivity(error: boolean): void {
    this.persistence.writeJson<IndexActivity>(INDEX_ACTIVITY, {
      lastActivity: new Date().toISOString(),
      error,
    });
  }
}
import { Citation, Chunk, Document, QAHistory, QAResponse } from '../shared/types';
import { IndexingService } from './indexing-service';
import { PersistenceService } from './persistence-service';

const QA_HISTORY_FILE = 'qa-history.json';
const STOP_WORDS = new Set([
  'about', 'and', 'are', 'can', 'does', 'for', 'from', 'how', 'the', 'this',
  'was', 'what', 'when', 'where', 'which', 'with', 'would',
]);

interface RankedChunk {
  chunk: Chunk;
  score: number;
}

export class QaService {
  private persistence: PersistenceService;
  private indexingService: IndexingService;

  constructor(persistence: PersistenceService, indexingService?: IndexingService) {
    this.persistence = persistence;
    this.indexingService = indexingService ?? new IndexingService(persistence);
  }

  /** Retrieve relevant indexed passages and produce an extractive answer. */
  async ask(question: string): Promise<QAResponse> {
    const terms = this.tokenize(question);
    const ranked = this.rankChunks(this.indexingService.getAllChunks(), terms).slice(0, 3);
    const documents = this.persistence.readJson<Document[]>('documents-meta.json') ?? [];
    const citations = ranked.map(({ chunk }) => this.createCitation(chunk, documents));
    const answer = this.generateAnswer(ranked, citations, terms);

    const response: QAResponse = {
      answer,
      citations,
      confidence: citations.length === 0 ? 0 : Math.min(0.95, 0.55 + ranked[0].score * 0.1),
      timestamp: new Date().toISOString(),
    };

    this.saveToHistory(question, response);
    return response;
  }

  getHistory(): QAHistory[] {
    return this.persistence.readJson<QAHistory[]>(QA_HISTORY_FILE) ?? [];
  }

  private rankChunks(chunks: Chunk[], terms: string[]): RankedChunk[] {
    if (terms.length === 0) return [];

    return chunks
      .map(chunk => {
        const words = new Set(this.tokenize(chunk.content));
        const score = terms.reduce((total, term) => total + (words.has(term) ? 1 : 0), 0);
        return { chunk, score };
      })
      .filter(result => result.score > 0)
      .sort((left, right) => right.score - left.score || left.chunk.index - right.chunk.index);
  }

  private createCitation(chunk: Chunk, documents: Document[]): Citation {
    const document = documents.find(candidate => candidate.id === chunk.documentId);
    return {
      documentId: chunk.documentId,
      documentTitle: document?.title ?? 'Unknown document',
      chunkIndex: chunk.index,
      excerpt: chunk.content.slice(0, 240),
    };
  }

  private generateAnswer(ranked: RankedChunk[], citations: Citation[], terms: string[]): string {
    if (citations.length === 0) {
      return 'I could not find a relevant passage in the indexed documents. Import and index a document, or use more specific terms.';
    }

    const sentences = ranked
      .flatMap(({ chunk }) => chunk.content.split(/(?<=[.!?])\s+|\n+/))
      .map(sentence => sentence.trim())
      .filter(sentence => sentence.length > 0)
      .map(sentence => ({
        sentence,
        score: terms.reduce((total, term) =>
          total + (this.tokenize(sentence).includes(term) ? 1 : 0), 0),
      }))
      .filter(candidate => candidate.score > 0)
      .sort((left, right) => right.score - left.score)
      .slice(0, 3)
      .map(candidate => candidate.sentence);

    const uniqueSentences = [...new Set(sentences)];
    const supportingText = uniqueSentences.join(' ');
    if (!supportingText) {
      return `The most relevant passage is in "${citations[0].documentTitle}": ${citations[0].excerpt}`;
    }

    return supportingText;
  }

  private tokenize(text: string): string[] {
    return [...new Set(
      (text.toLowerCase().match(/[a-z0-9]+/g) ?? [])
        .filter(word => word.length > 2 && !STOP_WORDS.has(word))
    )];
  }

  private saveToHistory(question: string, response: QAResponse): void {
    const history = this.getHistory();
    history.unshift({ question, response });
    this.persistence.writeJson(QA_HISTORY_FILE, history.slice(0, 50));
  }
}

import { BrowserWindow, dialog, IpcMain } from 'electron';
import { DocumentService } from '../services/document-service';
import { IndexingService } from '../services/indexing-service';
import { QaService } from '../services/qa-service';
import { IPC_CHANNELS } from '../shared/types';

export interface Services {
  documentService: DocumentService;
  indexingService: IndexingService;
  qaService: QaService;
}

export function registerIpcHandlers(ipcMain: IpcMain, services: Services) {
  const { documentService, indexingService, qaService } = services;

  // Document operations
  ipcMain.handle(IPC_CHANNELS.LIST_DOCUMENTS, async () => {
    return documentService.listDocuments();
  });

  ipcMain.handle(IPC_CHANNELS.SELECT_DOCUMENTS, async event => {
    const parentWindow = BrowserWindow.fromWebContents(event.sender);
    const options = {
      title: 'Import documents',
      properties: ['openFile', 'multiSelections'] as Array<'openFile' | 'multiSelections'>,
      filters: [{ name: 'Documents', extensions: ['md', 'txt'] }],
    };
    const result = parentWindow
      ? await dialog.showOpenDialog(parentWindow, options)
      : await dialog.showOpenDialog(options);

    if (result.canceled) return [];
    return result.filePaths.map(filePath => documentService.importDocument(filePath));
  });

  ipcMain.handle(IPC_CHANNELS.IMPORT_DOCUMENT, async (_event, filePath: string) => {
    return documentService.importDocument(filePath);
  });

  ipcMain.handle(IPC_CHANNELS.GET_DOCUMENT, async (_event, id: string) => {
    return documentService.getDocument(id);
  });

  ipcMain.handle(IPC_CHANNELS.GET_DOCUMENT_CONTENT, async (_event, id: string) => {
    return documentService.getDocumentContent(id);
  });

  ipcMain.handle(IPC_CHANNELS.DELETE_DOCUMENT, async (_event, id: string) => {
    indexingService.deleteIndex(id);
    return documentService.deleteDocument(id);
  });

  // Indexing
  ipcMain.handle(IPC_CHANNELS.START_INDEXING, async (_event, documentId?: string) => {
    return indexingService.startIndexing(documentId);
  });

  ipcMain.handle(IPC_CHANNELS.GET_INDEXING_STATUS, async () => {
    return indexingService.getStatus();
  });

  ipcMain.handle(IPC_CHANNELS.GET_CHUNKS, async (_event, documentId: string) => {
    return indexingService.getChunksForDocument(documentId);
  });

  // Q&A
  ipcMain.handle(IPC_CHANNELS.ASK_QUESTION, async (_event, question: string) => {
    return qaService.ask(question);
  });

  ipcMain.handle(IPC_CHANNELS.GET_HISTORY, async () => {
    return qaService.getHistory();
  });
}
